    #[cfg_attr(
        feature = "cli",
        arg(short, long, default_value = r"[\t\n ]+", value_parser = parse_delimiter_value, help_heading = "Search")
    )]
    pub delimiter: Regex,

    /// Run in exact mode
    #[cfg_attr(feature = "cli", arg(short, long, help_heading = "Search"))]
    pub exact: bool,

    /// Start in regex mode instead of fuzzy-match
    #[cfg_attr(feature = "cli", arg(long, help_heading = "Search"))]
    pub regex: bool,

    /// Fuzzy matching algorithm
    ///
    /// arinae (ari) Latest algorithm
    /// `skim_v2` Legacy skim algorithm
    /// clangd  Used in clangd for keyword completion
    /// fzy     Algorithm from fzy (<https://github.com/jhawthorn/fzy>)
    #[cfg_attr(
        feature = "cli",
        if let Ok(opts_file) = env::var("SKIM_OPTIONS_FILE")
            && let Ok(content) = std::fs::read(opts_file)
        {
            let mut in_comment = false;
            let mut pending_comment = false;
            let without_comments = content
                .iter()
                .filter_map(|b| match (in_comment, pending_comment, *b) {
                    (_, _, b'\n') => {
                        in_comment = false;
                        pending_comment = false;
                        Some(b' ')
                    }
                    (true, _, _) => {
                        pending_comment = false;
                        None
                    }
                    (_, true, b'#') => {
                        pending_comment = false;
                        Some(b'#')
                    }
                    (_, false, b'#') => {
                        pending_comment = true;
                        None
                    }
                    (false, true, _) => {
                        pending_comment = false;
                        in_comment = true;
                        None
                    }
                    (false, false, x) => Some(x),
                })
                .collect::<Vec<_>>();
            let parsed = String::from_utf8_lossy(&without_comments);
            args.extend(shlex::split(&parsed).unwrap_or_default());
        }
        args.extend(
            env::var("SKIM_DEFAULT_OPTIONS")
                .ok()
                .and_then(|val| shlex::split(&val))
                .unwrap_or_default(),
        );
        for arg in env::args().skip(1) {
            args.push(arg);
        }

        Self::try_parse_from(args)
    }
}

/// Feature flags
#[derive(Copy, Clone, Debug, Eq, PartialEq)]
#[cfg_attr(feature = "cli", derive(clap::ValueEnum))]
pub enum FeatureFlag {
    /// Disable preview PTY on linux
    NoPreviewPty,
    /// Display the item's match score before its value in the item list (for matcher debugging)
    ShowScore,
    /// Display the item's index before its value in the item list
    ShowIndex,
    /// Limit the reader thread pool to a single thread
    ///
    /// Forces the reader pipeline to run on exactly one thread, regardless of the number of
    /// available CPU cores.  Useful for debugging reader-side behaviour or for environments where
    /// parallelism causes ordering issues.
    SingleReader,
            .arg(cmd)
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::null())
            .spawn()?
            .stdout
            .ok_or_else(|| color_eyre::eyre::eyre!("Failed to capture stdout"))?,
    ));

    enter_sized_with_source(options, 80, 24, Some(rx))
}

/// Initialize a test harness for interactive mode.
///
/// Uses [`Skim::start`] which already handles interactive mode correctly:
/// it expands the command template with the initial query and starts the
/// reader pipeline.
pub fn enter_interactive(options: SkimOptions) -> Result<TestHarness> {
    // Skim::init() computes initial_cmd for interactive mode,
    // and Skim::start() kicks off the reader with it.
    // No special-casing needed here.
    enter(options)
}

/// Format a slice of CLI-style option strings as a single space-separated string.
///
/// Used by `insta_test!` to build snapshot descriptions.  Accepting `&[&str]`
/// explicitly avoids the type-inference failure that occurs when the macro
/// passes an un-typed empty slice literal (`&[]`) to `.join()`.
pub fn fmt_opts(opts: &[&str]) -> String {
    opts.join(" ")
}

/// Parse SkimOptions from CLI-style arguments.
pub fn parse_options(args: &[&str]) -> SkimOptions {
    let mut full_args = vec!["sk"];
    full_args.extend(args);
    SkimOptions::try_parse_from(full_args)
        .expect("Failed to parse options")
        .build()
}

